<script>
const urls={catalog:@json(route('bills.catalog')),validate:@json(route('bills.validate')),purchase:@json(route('bills.purchase', ['id'=>'__ID__'])),show:@json(route('bills.show', ['id'=>'__ID__']))};const sandboxProviders=@json($sandboxProviders);
const $=id=>document.getElementById(id);let validation=null,latestItems=[],billModal=null;
function errorText(text=''){ $('errorBox').textContent=text; }
function updateProviderEnvironment(){const provider=$('provider').value,sandbox=sandboxProviders.includes(provider);$('providerHelp').hidden=!sandbox;$('providerHelp').textContent=sandbox?((provider==='vtpass'?'VTpass':'Monnify')+' sandbox is for testing only. You can browse test options, but bill purchases are disabled until the admin switches it to live mode.'):'';$('reviewBtn').disabled=sandbox}
async function fetchCatalog(biller=''){const url=new URL(urls.catalog,location.origin);url.searchParams.set('provider',$('provider').value);url.searchParams.set('category',$('category').value);if(biller)url.searchParams.set('biller',biller);const res=await fetch(url,{headers:{Accept:'application/json'}});const data=await res.json();if(!res.ok)throw new Error(data.message||'Could not load options');return data.items||[]}
async function loadBillers(){const select=$('biller');select.disabled=true;select.innerHTML='<option>Loading available billers…</option>';errorText('');$('productWrap').hidden=true;$('product').innerHTML='<option value="">Choose a plan</option>';try{latestItems=await fetchCatalog();select.innerHTML='<option value="">Choose a provider</option>'+latestItems.map(x=>'<option value="'+escapeHtml(x.code)+'">'+escapeHtml(x.name)+'</option>').join('');$('billerHelp').textContent=latestItems.length?'Live options from '+$('provider').value+'.':'No options were returned for this service.';select.disabled=!latestItems.length}catch(e){select.innerHTML='<option value="">Unavailable</option>';errorText(e.message)}finally{select.disabled=false}}
async function loadProducts(){const c=$('category').value,p=$('provider').value;if(!['monnify'].includes(p)&&!['data','cable_tv'].includes(c)){ $('productWrap').hidden=true;return }const select=$('product');select.disabled=true;select.innerHTML='<option>Loading plans…</option>';try{const items=await fetchCatalog($('biller').value);select.innerHTML='<option value="">Choose a plan</option>'+items.map(x=>'<option value="'+escapeHtml(x.code)+'" data-amount="'+(x.amount??'')+'">'+escapeHtml(x.name)+(x.amount?' · ₦'+Number(x.amount).toLocaleString():'')+'</option>').join('');$('productWrap').hidden=!items.length;select.disabled=!items.length}catch(e){$('productWrap').hidden=true;errorText(e.message)}finally{select.disabled=false}}
function escapeHtml(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
$('provider')?.addEventListener('change',()=>{updateProviderEnvironment();if($('category').value)loadBillers()});$('category').addEventListener('change',()=>{const c=$('category').value;$('meterTypeWrap').hidden=c!=='electricity';$('biller').value='';if(c)loadBillers();else $('biller').innerHTML='<option>Choose a service first</option>'});$('biller').addEventListener('change',()=>{if($('biller').value)loadProducts()});$('product').addEventListener('change',()=>{const amount=$('product').selectedOptions[0]?.dataset.amount;if(amount){$('amount').value=amount;$('amount').readOnly=true}else $('amount').readOnly=false;updateAmount()});$('amount').addEventListener('input',updateAmount);updateProviderEnvironment();if($('category').value){$('meterTypeWrap').hidden=$('category').value!=='electricity';loadBillers()}
function updateAmount(){$('summaryAmount').textContent='₦'+(Number($('amount').value||0)).toLocaleString('en-NG',{minimumFractionDigits:2,maximumFractionDigits:2})}
function showBillReview(data){validation=data;const service=$('product').selectedOptions[0]?.textContent||$('biller').selectedOptions[0]?.textContent||'Bill payment';$('confirmService').textContent=($('provider').selectedOptions[0]?.textContent||'')+' · '+service;$('confirmAccount').textContent=$('identifier').value.trim();$('confirmPhone').textContent=$('phone').value.trim();$('confirmAmount').textContent='₦'+Number(data.amount).toLocaleString('en-NG',{minimumFractionDigits:2,maximumFractionDigits:2});$('confirmReference').textContent=data.reference;$('confirmNameLabel').hidden=!data.customer_name;$('confirmName').hidden=!data.customer_name;$('confirmName').textContent=data.customer_name||'—';$('pinError').textContent='';$('confirmPin').value='';billModal=bootstrap.Modal.getOrCreateInstance($('billConfirmModal'));billModal.show()}
$('billConfirmModal').addEventListener('shown.bs.modal',()=> $('confirmPin').focus());$('billConfirmModal').addEventListener('hidden.bs.modal',()=>{$('confirmPin').value='';$('pinError').textContent='';validation=null});
$('billForm').addEventListener('submit',async e=>{e.preventDefault();errorText('');const btn=$('reviewBtn');btn.disabled=true;btn.innerHTML='<span class="spinner-border spinner-border-sm me-2" aria-hidden="true"></span>Checking details…';try{const payload={provider:$('provider').value,category:$('category').value,biller_code:$('biller').value,service_code:$('biller').value,product_code:$('product').value||null,customer_identifier:$('identifier').value.trim(),phone:$('phone').value.trim(),amount:$('amount').value,type:$('meterType').value};const res=await fetch(urls.validate,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':@json(csrf_token()),Accept:'application/json'},body:JSON.stringify(payload)});const data=await res.json();if(!res.ok)throw new Error(Object.values(data.errors||{})[0]?.[0]||data.message||'Could not verify these bill details.');showBillReview(data)}catch(err){errorText(err.message)}finally{btn.innerHTML='<i class="bi bi-shield-check me-1"></i>Verify and review';updateProviderEnvironment()}});
$('confirmBillForm').addEventListener('submit',async e=>{e.preventDefault();$('pinError').textContent='';if(!validation||!/^\d{4}$/.test($('confirmPin').value)){ $('pinError').textContent='Enter your 4-digit transaction PIN.';return}const btn=$('authorizeBillBtn');btn.disabled=true;btn.innerHTML='<span class="spinner-border spinner-border-sm me-2" aria-hidden="true"></span>Authorizing…';try{const res=await fetch(urls.purchase.replace('__ID__',validation.id),{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':@json(csrf_token()),Accept:'application/json'},body:JSON.stringify({pin:$('confirmPin').value})});if(!res.ok){let data={};try{data=await res.json()}catch{}const message=Object.values(data.errors||{})[0]?.[0]||data.message||(res.status===429?'Too many payment attempts. Please wait a moment and try again. Your wallet was not charged.':'Payment could not be authorized. Please try again.');throw new Error(res.status===429?'Too many payment attempts. Please wait a moment and try again. Your wallet was not charged.':message)}if(res.redirected){window.location.assign(res.url);return}window.location.assign(urls.show.replace('__ID__',validation.id))}catch(err){$('pinError').textContent=err.message;$('confirmPin').value='';$('confirmPin').focus()}finally{btn.disabled=false;btn.innerHTML='<i class="bi bi-lock-fill me-1"></i>Pay securely'}});
</script>
@endif
